export type MessageKey = keyof typeof messages.en;
export const connectMessages = messages;

const validationKeys: Record<string, MessageKey> = {
  'Укажите название клуба': 'wizardValidationName',
  'Укажите город': 'wizardValidationCity',
  'Укажите адрес площадки': 'wizardValidationAddress',
  'Укажите сайт или соцсети': 'wizardValidationWebsite',
  'Похоже на неполный адрес': 'wizardValidationWebsiteFormat',
  'Укажите контакт для связи': 'wizardValidationContact',
  'Нужен e-mail или телефон': 'wizardValidationContactFormat',
  'Выберите хотя бы одно направление': 'wizardValidationGenres',
  'Укажите название площадки': 'wizardValidationVenue',
  'Укажите адрес': 'wizardValidationAddress',
  'Вместимость числом': 'wizardValidationCapacity',
  'Слишком большое значение': 'wizardValidationCapacityLarge',
  'Число посадочных мест': 'wizardValidationSeats',
  'Площадь в м²': 'wizardValidationArea',
  'Минимум 1,00 € за запрос': 'wizardValidationMinPrice',
  'Максимум 50,00 € за запрос': 'wizardValidationMaxPrice',
  'Добавьте хотя бы одну зону': 'wizardValidationZone',
  'Подтвердите условия тарифа': 'wizardValidationAccept',
};

export function translateValidationMessage(message: string | undefined, t: (key: MessageKey) => string) {
  const key = message ? validationKeys[message] : undefined;
  return key ? t(key) : message;
}
